const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Polygon(
    [[[120.9, 30.6],
      [120.9, 31.8],
      [121.9, 31.8],
      [121.9, 30.6],
      [120.9, 30.6]]]
  );

  const start1 = '2020-02-10';
  const end1 = '2020-02-25';
  const start2 = '2020-04-20';
  const end2 = '2020-05-12';

  const bandName = 'tropospheric_NO2_column_number_density';
  const scale = 3000; // Resolution for reduction, S5P is ~5.5km x 3.5km

  // Function to get and process image collection for a given period
  const processCollection = (startDate, endDate, geometry) => {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select([bandName, 'qa_value']);

    if (collection.size().getInfo() === 0) {
      return {
        collectionSize: 0,
        meanValue: null,
        validPixels: 0
      };
    }

    // Filter by quality assurance value (0-1, usually > 0.75 for good data)
    collection = collection.filter(ee.Filter.gt('qa_value', 0.75));

    if (collection.size().getInfo() === 0) {
      return {
        collectionSize: 0, // After QA filtering, collection might become empty
        meanValue: null,
        validPixels: 0
      };
    }

    const composite = collection.mean();

    // Calculate valid pixels
    const pixelCount = composite.select(bandName).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    if (pixelCount === 0) {
      return {
        collectionSize: collection.size().getInfo(),
        meanValue: null,
        validPixels: 0
      };
    }

    // Calculate mean NO2 value
    const meanNO2 = composite.select(bandName).reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    return {
      collectionSize: collection.size().getInfo(),
      meanValue: meanNO2,
      validPixels: pixelCount
    };
  };

  // 2. Data Acquisition & Check for Period 1
  const result1 = processCollection(start1, end1, shanghai);
  console.log(`Period 1 (${start1} to ${end1}):`);
  console.log(`  Images in collection: ${result1.collectionSize}`);

  if (result1.collectionSize === 0) {
    console.log("No images found for Period 1 after quality filtering.");
    console.log("C1");
    return;
  }
  if (result1.validPixels === 0) {
    console.log("No valid pixels remain for Period 1 after masking/clipping.");
    console.log("C2");
    return;
  }
  if (result1.meanValue === null || isNaN(result1.meanValue)) {
    console.log("Calculation failure for Period 1 mean NO2.");
    console.log("C3");
    return;
  }
  console.log(`  Valid pixels for mean: ${result1.validPixels}`);
  console.log(`  Mean NO2 (mol/m^2): ${result1.meanValue.toFixed(8)}`);


  // 3. Data Acquisition & Check for Period 2
  const result2 = processCollection(start2, end2, shanghai);
  console.log(`Period 2 (${start2} to ${end2}):`);
  console.log(`  Images in collection: ${result2.collectionSize}`);

  if (result2.collectionSize === 0) {
    console.log("No images found for Period 2 after quality filtering.");
    console.log("C1");
    return;
  }
  if (result2.validPixels === 0) {
    console.log("No valid pixels remain for Period 2 after masking/clipping.");
    console.log("C2");
    return;
  }
  if (result2.meanValue === null || isNaN(result2.meanValue)) {
    console.log("Calculation failure for Period 2 mean NO2.");
    console.log("C3");
    return;
  }
  console.log(`  Valid pixels for mean: ${result2.validPixels}`);
  console.log(`  Mean NO2 (mol/m^2): ${result2.meanValue.toFixed(8)}`);

  // 4. Comparison and Final Answer
  if (result2.meanValue > result1.meanValue) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
